1	import java.util.List;
2	
3	/**
4	 * A class representing plants in the simulation. It extends
5	 * the abstract class Species
6	 *
7	 * @version 2022.02.28
8	 */
9	public class Plant extends Species
10	{
11	    // The plant's maximum health
12	    private int maxHealth;
13	    // The probability that the plant's health grows
14	    private static final double GROWING_PROBABILITY = 0.1;
15	    // Keep track of the plant's health
16	    private int currentHealth;
17	    // true if the current season is Spring
18	    private boolean isSpring;
19	    // true if the plant can regrow, needs at least one season till it is true again
20	    private boolean canRegrow;
21	    // true if plant appears dead due to temperature circumstances
22	    private boolean deadDueTemperature;
23	
24	    /**
25	     * Create an instance of Plant
26	     *
27	     * @param field (Field) The field currently occupied.
28	     * @param location (Location) The location within the field.
29	     * @param name (String) The name of the plant
30	     * @param maximumTemperature (int) The maximum temperature that the plant can withstand
31	     * @param minimumTemperature (int) The minimum temperature that the plant can withstand
32	     * @param nutritionalValue (int) The nutritional value given to the specie that eats this plant
33	     * @param reproductionProbability (double) The probability that this plant will reproduce
34	     * @param maxHealth (int) The plant's maximum health
35	     */
36	    public Plant(Field field, Location location, String name, int maximumTemperature, int minimumTemperature, int nutritionalValue, double reproductionProbability, int maxHealth)
37	    {
38	        super(field, location, name, maximumTemperature, minimumTemperature, nutritionalValue, reproductionProbability);
39	        this.maxHealth = maxHealth;
40	        currentHealth = maxHealth;
41	        isSpring = true;
42	        canRegrow = true;
43	        deadDueTemperature = false;
44	    }
45	
46	    /**
47	     * Imitate a plant's step by doing the following:
48	     * 1) if the plant can't survive the temperature, then it dies
49	     * 2) else if the time is day:
50	     *      i) if the plant is dead, and it's spring, and the temperature is suitable,
51	     *         then grow back
52	     *      ii) else if the plant is alive, then
53	     *          a) increase max health by 1 if it lived for a year
54	     *          b) reproduce and grow
55	     *
56	     * @param newPlants (List<Species>) A list to return the new plants created.
57	     * @param isNight (boolean) true if it is night in the simulation
58	     * @param temperature (int) The current temperature of the simulation
59	     * @param yearPassed (boolean) True if a year has passed in the simulation
60	     */
61	    public void act(List<Species> newPlants, boolean isNight, int temperature, boolean yearPassed)
62	    {
63	        // 1)
64	        if (! deadDueTemperature && ! survivesTemperature(temperature))
65	        {
66	            wilt();
67	        }
68	        // 2)
69	        else if (! isNight)
70	        {
71	            // i)
72	            if (deadDueTemperature && survivesTemperature(temperature) && isSpring) {
73	                regrow();
74	            }
75	            // ii)
76	            else if (! deadDueTemperature) {
77	                // a)
78	                if (yearPassed) {
79	                    maxHealth++;
80	                }
81	                // b)
82	                reproduce(newPlants);
83	                grow();
84	            }
85	        }
86	    }
87	
88	    /**
89	     * Add a new plant in a free neighbouring location if the two
90	     * following conditions are met:
91	     * 1- The production probability meets the random number
92	     * 2- There is a free adjacent location.
93	     *
94	     * @param newPlants (list<Species>)A list to return the new plant
95	     */
96	    protected void reproduce(List<Species> newPlants)
97	    {
98	        if (rand.nextDouble() <= getReproductionProbability())
99	        {
100	            Field field = getField();
101	            if (field != null)
102	            {
103	                List<Location> free = field.getFreeAdjacentLocations(getLocation());
104	
105	                if (free.size() > 0) {
106	                    Location loc = free.remove(0);
107	                    Plant newPlant = new Plant(field, loc, getName(), getMaximumTemperature(), getMinimumTemperature(), getNutritionalValue(), getReproductionProbability(), maxHealth);
108	                    newPlant.setIsSpring(isSpring);
109	                    newPlants.add(newPlant);
110	                }
111	            }
112	        }
113	    }
114	
115	    /**
116	     * The plant wilts due to temperature: it is removed from the field but remains in the
117	     * species list so it can regrow in spring. Unlike permanent death (when eaten), the
118	     * plant's alive state is unchanged and its field/location references are preserved.
119	     */
120	    private void wilt()
121	    {
122	        if(getLocation() != null) {
123	            deadDueTemperature = true;
124	            canRegrow = false; // prevent immediate regrowth next step
125	            getField().clear(getLocation());
126	        }
127	    }
128	
129	    /**
130	     * The dead plant is placed back in the field if its previous location is empty and can regrow, otherwise do nothing.
131	     * If it grows, then it grows back to full health.
132	     */
133	    private void regrow()
134	    {
135	        if(getField().getObjectAt(getLocation()) == null && canRegrow)   {
136	            deadDueTemperature = false;
137	            getField().place(this, getLocation());
138	            currentHealth = maxHealth;
139	        }
140	    }
141	
142	    /**
143	     * Increase the plant's health by one if the random number meets the growing probability
144	     */
145	    private void grow()
146	    {
147	        if (currentHealth < maxHealth && rand.nextDouble() <= GROWING_PROBABILITY) {
148	            currentHealth++;
149	        }
150	    }
151	
152	    /**
153	     * The effect of getting eaten by an animal.
154	     * Decrement currentHealth by one, and set dead if the current health is less than 1.
155	     */
156	    public void isEaten()
157	    {
158	        currentHealth--;
159	
160	        if (currentHealth <= 0)    {
161	            super.setDead();
162	        }
163	    }
164	
165	    /**
166	     * If isSpring is true, then change it to false, vice versa.
167	     *Also, set canRegrow as true because at least a season has passed since the plant died.
168	     */
169	    public void toggleIsSpring()
170	    {
171	        isSpring = ! isSpring;
172	        canRegrow = true;
173	    }
174	
175	    /**
176	     * @return (boolean) true if the current season is spring, false otherwise.
177	     */
178	    public boolean getIsSpring()
179	    {
180	        return isSpring;
181	    }
182	
183	    /**
184	     * Set the isSpring value to the given parameter
185	     *
186	     * @param spring (boolean) true if it is spring, false otherwise.
187	     */
188	    private void setIsSpring(boolean spring)
189	    {
190	        isSpring = spring;
191	    }
192	}
